<style scoped lang="scss" src="./video.scss"></style>

<script lang="js">
import { Component, Prop, Vue } from "vue-property-decorator";
import Icon from "../../components/icon/icon.vue";
import { IconShape } from "../../components/icon/icon.constants.js"

/**
 * It is a component to provide a basic mp4 video player
 */
@Component({
  components: {
    Icon
  }
})
export default class Video extends Vue {
  @Prop({
    type: String,
    default: "",
  }) src;
  @Prop({
    type: String,
    default: "",
  }) image;

  playing = false;
  IconShape = IconShape;
  videoWidth = 0;
  videoHeight = 0;

  backgroundUrl = "";
  vimeo_id = 0;

  beforeMount() {
    this.playing = false;
    this.backgroundUrl = "";
  }

  mounted() {
    if (this.isYoutube) {
      const id = this.getYoutubeVideoId(this.src);
      const imageUrl = `https://img.youtube.com/vi/${id}/maxresdefault.jpg`;

      this.backgroundUrl = this.image || imageUrl;
    }

    else if (this.isVimeo) {
      fetch(`https://vimeo.com/api/oembed.json?url=${this.src}`)
        .then(response => response.json())
        .then(data =>  {
          console.warn(data);
          this.vimeo_id = data.video_id;
          this.backgroundUrl = this.image || data.thumbnail_url;
        });
    }

    else {
      this.backgroundUrl = this.image;
    }
  }

  getYoutubeVideoId(url) {
    let video_id = url.split('v=')[1];

    if(video_id) {
      const ampersandPosition = video_id.indexOf('&');

      if(ampersandPosition != -1) {
        video_id = video_id.substring(0, ampersandPosition);
      }
    }

    return video_id;
  }

  get backgroundStyle() {
    if (this.playing) {
      return {
        background: "#000000"
      }
    }

    return {
      backgroundImage: `url(${this.backgroundUrl})`
    };
  }

  get isPlaying() {
    return this.playing;
  }

  get isYoutube() {
    return !this.src.split(/(?:https?:\/\/)?(?:www\.)?youtu(?:\.be\/|be.com\/\S*(?:watch|embed)(?:(?:(?=\/[^&\s\?]+(?!\S))\/)|(?:\S*v=|v\/)))([^&\s\\?]+)/g)[0];
  }

  get isVimeo() {
    return /(https?:\/\/)?(www\.)?(player\.)?vimeo\.com\/([a-z]*\/)*([‌​0-9]{6,11})[?]?.*/.test(this.src);
  }

  get youtubeUrl() {
    const id = this.getYoutubeVideoId(this.src);
    return `https://www.youtube.com/embed/${id}`
  }

  get vimeoUrl() {
    if(this.vimeo_id) {
      return `https://player.vimeo.com/video/${this.vimeo_id}`
    }

    return "";
  }

  onClick() {
    if (this.$refs.videoBox) {
      this.videoHeight = this.$refs.videoBox.clientHeight;
      this.videoWidth = this.$refs.videoBox.clientWidth;
    }

    this.playing = true;
  }

  quit() {
    this.playing = false;
  }
}
</script>

<template>
  <div class="Video" v-bind:style="backgroundStyle" ref="videoBox">
    <div v-if="!isPlaying" class="Video__PlayButton" @click="onClick">
      <Icon :shape="IconShape.ARROW_RIGHT" :size="24.21" :color="'#FFFFFF'" />
    </div>
    <div v-else-if="isYoutube">
      <iframe :width="videoWidth" :height="videoHeight" :src="youtubeUrl" />
    </div>
    <div v-else-if="isVimeo">
      <iframe :width="videoWidth" :height="videoHeight" :src="vimeoUrl" />
    </div>
    <div v-else class="Video__Container">
      <video class="Video__Content" autoplay controls>
        <source :src="src" type="video/mp4" />
      </video>
    </div>
  </div>
</template>
